import zipfile
import os

def compress_file(input_file, output_zip, compression_level=6):
    """
    Compress a file using ZIP compression.

    Args:
        input_file (str): Path to the input file to compress
        output_zip (str): Path for the output ZIP file
        compression_level (int): Compression level from 0-9 (0=none, 9=max)
    """
    if not os.path.exists(input_file):
        raise FileNotFoundError(f"Input file {input_file} does not exist")

    # Map compression level to ZIP compression method
    compression_method = {
        0: zipfile.ZIP_STORED,
        **{i: zipfile.ZIP_DEFLATED for i in range(1, 10)}
    }[min(compression_level, 9)]

    try:
        with zipfile.ZipFile(output_zip, 'w', compression_method) as zipf:
            zipf.write(input_file, arcname=os.path.basename(input_file))
        print(f"Successfully compressed {input_file} to {output_zip}")
    except Exception as e:
        print(f"Error during compression: {e}")
        raise

def batch_compress(input_files, output_zip, compression_level=6):
    """Compress multiple files into a single ZIP archive."""
    compression_method = {
        0: zipfile.ZIP_STORED,
        **{i: zipfile.ZIP_DEFLATED for i in range(1, 10)}
    }[min(compression_level, 9)]

    try:
        with zipfile.ZipFile(output_zip, 'w', compression_method) as zipf:
            for file_path in input_files:
                if os.path.exists(file_path):
                    zipf.write(file_path, arcname=os.path.basename(file_path))
        print(f"Successfully created archive {output_zip} with {len(input_files)} files")
    except Exception as e:
        print(f"Error during batch compression: {e}")
        raise

# Example usage
if __name__ == "__main__":
    compress_file('inputs/example.txt', 'outputs/example.zip', compression_level=6)
